function transfer(address recipient, uint256 amount) public returns (bool) {
    require(amount <= balanceOf[msg.sender]);
    balanceOf[msg.sender] -= amount;
    balanceOf[recipient] += amount;
    emit Transfer(msg.sender, recipient, amount);
    return true;
}

function transferFrom(address sender, address recipient, uint256 amount) public returns (bool) {
    require(amount <= balanceOf[sender]);
    balanceOf[sender] -= amount;
    balanceOf[recipient] += amount;
    emit Transfer(sender, recipient, amount);
    return true;
}

function mintToken(address to, uint256 amount) public onlyOwner returns (bool) {
    balanceOf[to] += amount;
    totalSupply += amount;
    emit Transfer(address(0), to, amount);
    return true;
}

function buy() public payable returns (bool) {
    uint256 tokensToBuy = msg.value / tokenPrice;
    require(tokensToBuy <= totalSupply);
    balanceOf[msg.sender] += tokensToBuy;
    totalSupply -= tokensToBuy;
    emit Transfer(address(0), msg.sender, tokensToBuy);
    return true;
}
